from pathlib import Path
p=Path('/home/user/work/render/render.py')
s=p.read_text(encoding='utf-8')

def rep(old,new, label):
    global s
    n=s.count(old)
    if n!=1:
        raise SystemExit(f'{label}: expected one match, got {n}')
    s=s.replace(old,new,1)
    print('patched',label)

